"use client";

import { useState } from "react";

export default function SearchPage() {
  const [keyword, setKeyword] = useState("");
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const handleSearch = async (searchValue?: string) => {
    const finalKeyword = searchValue || keyword;

    if (!finalKeyword.trim()) {
      alert("Please enter keyword");
      return;
    }

    try {
      setLoading(true);

      const res = await fetch(
        `http://127.0.0.1:8000/search/analytics?keyword=${encodeURIComponent(
          finalKeyword
        )}`
      );

      if (!res.ok) {
        throw new Error("Search API failed");
      }

      const data = await res.json();
      setResult(data);
      setKeyword(finalKeyword);
    } catch (error) {
      console.error(error);
      alert("Search failed. Check backend /search endpoint.");
    } finally {
      setLoading(false);
    }
  };

  const quickSearch = (item: string) => {
    handleSearch(item);
  };

  return (
    <main className="page search-page">
      <section className="page-hero search-hero">
        <p className="eyebrow">Smart Search</p>
        <h1>Smart Search Analytics</h1>
        <p>Search product/category/status and view users ordered, order count, quantity, and sales.</p>

        <div className="search-box">
          <input
            type="text"
            placeholder="Search electronics, mobile, laptop, completed..."
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") handleSearch();
            }}
          />
          <button onClick={() => handleSearch()} disabled={loading}>
            {loading ? "Searching..." : "Search"}
          </button>
        </div>

        <div className="quick-tags">
          <span>Try:</span>
          {["electronics", "mobile", "laptop", "completed", "pending"].map(
            (item) => (
              <button key={item} onClick={() => quickSearch(item)}>
                {item}
              </button>
            )
          )}
        </div>
      </section>

      <section className="stat-grid">
        <div className="stat-card">
          <div className="stat-icon">📦</div>
          <p>Products Found</p>
          <h2>{result?.products_found ?? 0}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">👥</div>
          <p>Users Ordered</p>
          <h2>{result?.users_ordered ?? 0}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🛒</div>
          <p>Orders Count</p>
          <h2>{result?.orders_count ?? 0}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📦</div>
          <p>Quantity Sold</p>
          <h2>{result?.quantity_sold ?? 0}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">₹</div>
          <p>Total Sales</p>
          <h2>₹{Number(result?.total_sales ?? 0).toFixed(2)}</h2>
        </div>
      </section>

      {result?.orders?.length > 0 && (
        <section className="table-card">
          <div className="section-title">
            <h2>{keyword} Results Table</h2>
            <p>{result.orders.length} records found</p>
          </div>

          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>ID</th>
                  <th>User ID</th>
                  <th>Status</th>
                  <th>Total Amount</th>
                  <th>Order Date</th>
                </tr>
              </thead>

              <tbody>
                {result.orders.map((order: any) => (
                  <tr key={order.id}>
                    <td>{order.id}</td>
                    <td>{order.user_id}</td>
                    <td>
                      <span className={`status-badge ${order.order_status}`}>
                        {order.order_status}
                      </span>
                    </td>
                    <td>₹{Number(order.total_amount ?? 0).toFixed(2)}</td>
                    <td>{order.order_date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}
    </main>
  );
}